gac8(){return"\u0623\u0631\u0634\u0641\u0629"},
gacF(){return"\u062d\u0630\u0641 \u0646\u0647\u0627\u0626\u064a"},
gadn(){return"\u0627\u0633\u062a\u0639\u0627\u062f\u0629"},
gacc(){return"\u0627\u0644\u0645\u0624\u0631\u0634\u0641\u0629"},
gacb(){return"\u0623\u0631\u0634\u0641\u0629 \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u062d\u0644\u0629\u061f"},
aca(a){return"\u0633\u062a\u064f\u0632\u0627\u0644 \xab"+a+"\xbb \u0645\u0646 \u0645\u0633\u0627\u0631 \u0643\u0644 \u0646\u0648\u0639 \u062d\u0627\u0644\u0629 \u0648\u0645\u0646 \u0627\u0644\u0644\u0648\u062d\u0629. \u062a\u062d\u062a\u0641\u0638 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0642\u062f\u064a\u0645\u0629 \u0648\u0627\u0644\u0633\u062c\u0644 \u0628\u0627\u0644\u0627\u0633\u0645. \u064a\u0645\u0643\u0646\u0643 \u0627\u0633\u062a\u0639\u0627\u062f\u062a\u0647\u0627 \u0644\u0627\u062d\u0642\u064b\u0627."},
