gacH(){return"\u062d\u0630\u0641 \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0646\u0647\u0627\u0626\u064a\u064b\u0627\u061f"},
acG(a){return"\u0633\u062a\u064f\u062d\u0630\u0641 \xab"+a+"\xbb \u0646\u0647\u0627\u0626\u064a\u064b\u0627. \u064a\u0639\u0645\u0644 \u0647\u0630\u0627 \u0641\u0642\u0637 \u0625\u0630\u0627 \u0644\u0645 \u062a\u0633\u062a\u062e\u062f\u0645\u0647\u0627 \u0623\u064a \u062d\u0627\u0644\u0629 \u0639\u0644\u0649 \u0627\u0644\u0625\u0637\u0644\u0627\u0642."},
gSE(){return"\u062a\u0645\u062a \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0645\u0631\u062d\u0644\u0629."},
gadB(){return"\u062a\u0645\u062a \u0627\u0633\u062a\u0639\u0627\u062f\u0629 \u0627\u0644\u0645\u0631\u062d\u0644\u0629."},
gacO(){return" \xb7 \u0627\u0633\u062a\u0642\u0628\u0627\u0644"},
gad8(){return"\u0646\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645"},
gad7(){return"\u0646\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641"},
gadA(){return"\u0627\u0644\u0627\u0633\u0645"},
gadx(){return"\u0627\u0644\u0644\u0648\u0646 (\u0647\u064a\u0643\u0633\u060c \u0645\u062b\u0627\u0644: FFB8763F)"},
gacn(){return"\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062d\u0627\u0644\u0627\u062a"},
